// Acorn Dice — an acorn-shaped d6 for Dice So Nice, for any game system.
//
// The die is a custom glTF model (dice/acorn-d6.glb, generated by
// tools/build_acorn.py) with its own physics shape: a hexagonal "long die"
// with pointed ends, read on the face that lands on top. The ends never score
// (face value 0), so a die balanced on a point reads its nearest numbered face.
// The result shown is always the result Foundry rolled: Dice So Nice turns the
// die at the end of the throw so that face is on top.

import { ACORN_SHAPE } from "./acorn-shape.js";

const MODULE_ID = "acorn-dice-litm";
const DICE_SYSTEM = "acorn-dice-litm";
const SETTING = "applyTo";                 // "all" | "player"

/** Folder this module is served from (works whatever the folder is called). */
const MODULE_ROOT = new URL("../", import.meta.url).pathname.replace(/^\//, "");

let registered = false;

Hooks.once("init", () => {
  game.settings.register(MODULE_ID, SETTING, {
    name: "ACORN_DICE.settings.applyTo.name",
    hint: "ACORN_DICE.settings.applyTo.hint",
    scope: "world", config: true, type: String, default: "all",
    choices: {
      all: "ACORN_DICE.settings.applyTo.all",
      player: "ACORN_DICE.settings.applyTo.player",
    },
  });
});

/** Dice So Nice's public DiceSystem class (its documented api.js), if available. */
async function loadDiceSystemClass() {
  try {
    const url = new URL(foundry.utils.getRoute("modules/dice-so-nice/api.js"), window.location.origin).href;
    return (await import(url)).DiceSystem ?? null;
  } catch {
    return null;
  }
}

Hooks.once("diceSoNiceReady", async (dice3d) => {
  if (typeof dice3d.addDiceShape !== "function") {
    ui.notifications?.warn(game.i18n.localize("ACORN_DICE.notify.updateDsn"), { permanent: true });
    return;
  }
  dice3d.addDiceShape(ACORN_SHAPE);

  const name = game.i18n.localize("ACORN_DICE.systemName");
  const DiceSystem = await loadDiceSystemClass();
  dice3d.addSystem(DiceSystem ? new DiceSystem(DICE_SYSTEM, name, "default", "Acorn Dice")
                              : { id: DICE_SYSTEM, name, group: "Acorn Dice" });
  dice3d.addDicePreset({
    type: "d6",
    system: DICE_SYSTEM,
    modelFile: `${MODULE_ROOT}dice/acorn-d6.glb`,
  }, ACORN_SHAPE.name);
  registered = true;
});

/**
 * "Every d6, for everyone": right before Dice So Nice shows a roll, give each
 * d6 the acorn look, unless the roll (or another module) already asked for a
 * specific dice set.
 */
Hooks.on("diceSoNiceRollStart", (_messageId, context) => {
  if (!registered || game.settings.get(MODULE_ID, SETTING) !== "all") return;
  const roll = context?.dsnRoll ?? context?.roll;
  for (const term of roll?.dice ?? []) {
    if (term.faces !== 6) continue;
    term.options ??= {};
    const appearance = (term.options.appearance ??= {});
    appearance.system ??= DICE_SYSTEM;
  }
});
